async function tick(n,opts){ const ck=Object.assign({t:0},st('clock')||{}); ck.t=(ck.t||0)+n; ck.rest=(opts&&opts.rest)?(ck.rest||0)+1:0; await setState('clock',ck); const t=ck.t; (st('lights')||[]).forEach(l=>{ if(l.lit!==false&&l.end!=null&&l.end<=t&&l.end>t-n) logEvent(`: ${l.name} burned out`); }); (st('effects')||[]).forEach(e=>{ if(e.end<=t&&e.end>t-n) logEvent(`: ${e.name} ended`); }); }

// ---------- more ----------
function viewMore(v){
  v.innerHTML=`<div class="card"><h2>Invite players</h2><div class="code">${esc(S.campaign.invite_code)}</div><p class="small mute" style="margin:6px 0 10px">Players open this app, create an account, and enter this code.</p><button class="btn sm sec" data-act="copyinvite">Copy invite</button></div>
   <div class="card"><h2>Dungeon Master</h2>${(()=>{ const dm=theDM(), q=S.campaign.dm_req, need=S.campaign.needed||1; if(honor()) return '<div>Honor system: there is no DM in the app. Everyone shares the referee tools.</div>'+(q?'':'<button class="btn sm sec" style="margin-top:10px" data-act="askdm">Ask to be the DM</button>');
      if(dm) return `<div><b>${esc(dm.name)}</b> is the Dungeon Master.</div>${dm.id===S.user.id?'<button class="btn sm sec" style="margin-top:10px" data-act="stepdown">Step down</button>':isOwner()?`<button class="btn sm sec" style="margin-top:10px" data-act="stepdown" data-u="${dm.id}">Remove as DM</button>`:''}`;
      if(q) return `<div><b>${esc(q.name)}</b> has asked to be the DM: ${q.count} of ${need} approval${need>1?'s':''} so far.</div>${q.user===S.user.id?'<button class="btn sm sec" style="margin-top:10px" data-act="votedm" data-v="0">Withdraw my request</button>':q.voted?'<div class="small mute" style="margin-top:6px">You approved.</div>':'<div class="row" style="margin-top:10px"><button class="btn sm" data-act="votedm" data-v="1">Approve</button><button class="btn sm sec" data-act="votedm" data-v="0">Decline</button></div>'}`;
      return `<div>No Dungeon Master yet. The clock, combat and DM tools stay locked until one is approved.</div><button class="btn sm" style="margin-top:10px" data-act="askdm">Ask to be the DM</button><div class="small mute" style="margin-top:6px">${need} other player${need>1?'s':''} must approve. Nobody can make themselves DM.</div>`; })()}</div>
   ${isOwner()?'':`<div class="card"><h2>Rule set</h2><div>${EDS[ED()]}</div><div class="small mute">${honor()?'Honor system: no DM in the app. ':''}Set by whoever created the campaign.</div></div>`}
   <div class="card"><h2>At the table</h2>${S.members.map(m=>`<div class="li" style="padding:7px 0"><span class="av${uk(m.id)}">${uav(m.id)}</span><div class="t">${esc(m.name)}${m.full&&m.full!==m.name?` <span class="mute small">(${esc(m.full)})</span>`:''}${m.role==='dm'?'<span class="tag dm">DM</span>':''}${S.campaign.owner===m.id?'<span class="tag">owner</span>':''}<small>${esc(CH().filter(c=>c.user_id===m.id).map(c=>c.data.name).join(', '))}</small></div></div>`).join('')}</div>
   ${isOwner()?`<div class="card"><h2>Table rules</h2><div class="small mute">You own this campaign.</div><label>Who runs the game in the app?</label><select data-change="mode"><option value="dm" ${honor()?'':'selected'}>A Dungeon Master, approved by the players</option><option value="honor" ${honor()?'selected':''}>No DM in the app (honor system)</option></select><label>Approvals needed to become DM</label><select data-change="needed">${[1,2,3].map(n=>`<option ${((S.campaign.needed||1)===n)?'selected':''}>${n}</option>`).join('')}</select><label>Hand the campaign to someone else</label><div class="row"><select id="own_to" style="flex:1"><option value="">Choose…</option>${S.members.filter(m=>m.id!==S.user.id).map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select><button class="btn sm sec" data-act="handover">Hand over</button></div><label>Rule set (edition)</label><select data-change="edition">${Object.keys(EDS).map(k=>`<option value="${k}" ${ED()===k?'selected':''}>${EDS[k]}</option>`).join('')}</select><div class="small mute" style="margin-top:4px">Characters belong to the rule set they were made under. Switching hides the others and restarts the clock.</div><label>How abilities are rolled</label><select id="set_method" data-change="method"><option value="3d6" ${((st('settings')||{}).method||'3d6')==='3d6'?'selected':''}>3d6 in order</option><option value="4d6" ${((st('settings')||{}).method)==='4d6'?'selected':''}>4d6, drop the lowest</option></select></div>`:''}
   <div class="card"><h2>Rules reference</h2>${R.reference.map(r=>`<details><summary>${esc(r[0])}</summary><p>${esc(r[1])}</p></details>`).join('')}
    <details><summary>Encumbrance</summary><table><tr><th>Load</th><th>Up to</th><th>Move</th><th>Reaction</th></tr>${R.encumbrance.map(e=>`<tr><td>${e[1]}</td><td>${e[0]===Infinity?'more':e[0].toLocaleString()+' '+R.wtUnit}</td><td>${e[2]}</td><td>${e[3]}</td></tr>`).join('')}</table><p>${R.id==='adnd1'?'Strength changes these limits. ':'Encumbrance is an optional rule. '}10 coins weigh one pound.</p></details>
    <details><summary>Light sources</summary><table><tr><th>Source</th><th>Radius</th><th>Burns</th></tr>${Object.keys(R.lights).map(k=>`<tr><td>${k}</td><td>${R.lights[k][0]}'</td><td>${R.lights[k][1]?R.lights[k][1]+' turns':'always'}</td></tr>`).join('')}</table></details>
    <details><summary>Armor classes</summary><table><tr><th>Armor</th><th>AC</th><th>With shield</th><th>Cost</th></tr>${R.armor.map(a=>`<tr><td>${a[0]}</td><td>${a[1]}</td><td>${a[1]-1}</td><td>${a[2]?a[2]+' g.p.':'—'}</td></tr>`).join('')}</table></details>
    <details><summary>Experience levels by class</summary>${R.classOrder.map(k=>{ const C=R.classes[k]; return `<p><b>${C.name}</b> (d${C.hd})</p><table>${C.xp.map((x,i)=>`<tr><td>${i+1} · ${esc(R.titleFor(k,i+1))}</td><td>${x.toLocaleString()}</td></tr>`).join('')}</table>${C.per?`<p class="small">${C.per.toLocaleString()} x.p. per level after that.</p>`:''}`; }).join('')}</details>${R.turn?`<details><summary>Turning undead</summary><table><tr><th>Undead</th><th>Level 1</th><th>Level 2</th><th>Level 3</th></tr>${R.turn.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</table><p>Roll 2d6 and meet the number. T turns automatically. Then 2d6 hit dice of undead are turned.</p></details>`:''}${R.saveNames?`<details><summary>Saving throws, levels 1 to 3</summary><table><tr><th>Class</th>${R.saveNames.map(n=>`<th>${n.split(' ')[0]}</th>`).join('')}</tr>${R.classOrder.map(k=>`<tr><td>${R.classes[k].name}</td>${R.classes[k].saves.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</table></details>`:''}
    <details><summary>Spell lists</summary>${Object.keys(R.spells).map(L=>`<p><b>${R.spellListNames[L]}</b></p>`+R.spells[L].map((l,i)=>R.spellInfo&&R.spellInfo[L]?`<p class="small gold" style="margin-bottom:0">Level ${i+1}</p>`+l.map(n=>{ const f=R.spellInfo[L][n]; return `<p class="small" style="margin:4px 0"><b>${esc(n)}</b>${f?` <span class="mute">· ${esc(f[0])} · ${esc(f[1])}</span><br>${esc(f[2])}`:''}</p>`; }).join(''):`<p class="small"><span class="gold">Level ${i+1}:</span> ${esc(l.join(', '))}</p>`).join('')).join('')}<p class="small mute">${R.spellInfo?'Short summaries; the full wording is':'Ranges, durations and effects are'} in your ${R.bookName}.</p></details></div>
   <div class="card"><h2>Weapons and prices</h2><button class="btn sm sec" data-act="weaponsref">Weapon table</button> <button class="btn sm sec" data-act="pricelist">Price list</button> <button class="btn sm sec" data-act="moneyconv">Coin converter</button></div>
   <div class="card"><h2>Your dice</h2><div class="row wrap">${Object.keys(THEMES).map(k=>`<button class="sw big ${S.dtheme===k?'on':''}" data-act="dtheme" data-k="${k}" aria-label="${THEMES[k][0]}" style="background:linear-gradient(135deg,${THEMES[k][1]},${THEMES[k][2]})"></button>`).join('')}</div><div class="small mute" style="margin-top:8px">Everyone sees your rolls in your colors. You can also change them when you roll.</div></div>
   <div class="card"><h2>Sound</h2><div class="row"><div class="grow">Background sound and effects</div><button class="btn sm ${SND.on?'':'sec'}" data-act="sound">${SND.on?'On':'Off'}</button></div><label>Volume</label><input type="range" id="vol" min="0" max="100" value="${Math.round(SND.vol*100)}" style="padding:0;min-height:32px;box-shadow:none;border:0;background:none;accent-color:#cfa84f"><div class="small mute">The default is a quiet cave with water dripping. It changes when the party moves somewhere new: dungeon halls, a crypt, an underground river, a forest, a hearth, a campfire, battle drums. Dice rattle when anyone rolls. On an iPhone, turn the volume up; it should play even with the ring switch off.</div></div>
   <p class="small mute" style="text-align:center">Atomic Sparkle, build 22</p>
   <div class="card"><h2>Put it on your home screen</h2><p class="small" style="margin:0"><b>iPhone:</b> open in Safari, tap Share, then “Add to Home Screen”.<br><b>Android:</b> open in Chrome, tap the menu, then “Install app” or “Add to Home screen”.</p></div>
   <div class="card"><h2>Your account</h2><div class="row" style="margin-bottom:10px"><span class="av big${uk(S.user.id)}" style="width:60px;height:60px;font-size:22px">${uav(S.user.id)}</span><div class="grow"><b>${esc(S.user.name)}</b><div class="small mute">${S.user.full?esc(S.user.full)+', ':''}${esc(fmtPhone(S.user.phone))}</div></div></div><label>Your picture in this game</label><select data-change="gameav">${(()=>{ const m=S.members.find(x=>x.id===S.user.id)||{}; return `<option value="letters" ${m.am==='letters'?'selected':''}>Just my initials</option><option value="" ${m.am!=='letters'&&!m.ac?'selected':''}>My account picture</option>`+myChars().map(c=>`<option value="${c.id}" ${(m.am!=='letters'&&m.ac===c.id)?'selected':''}>${esc(c.data.name||'Unnamed')}'s portrait</option>`).join(''); })()}</select><div class="small mute" style="margin:4px 0 10px">Each game can show a different picture of you. The frame around it comes from your character's class.</div><div class="row wrap"><button class="btn sm" data-act="account">Edit account</button><button class="btn sm sec" data-act="switch">Switch campaign</button><button class="btn sm danger" data-act="signout">Sign out</button></div>
   <p class="small mute" style="margin:10px 0 0">${esc(R.footer)}</p></div>`;
}

// ---------- small form modals ----------
function formModal(title,fields,onSave,extra){ modal(title,fields.map(f=>`<label>${esc(f.label)}</label>`+(f.type==='select'?`<select id="f_${f.id}">${f.options.map(o=>`<option ${String(f.value)===String(o)?'selected':''}>${esc(o)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea id="f_${f.id}" maxlength="6000">${esc(f.value||'')}</textarea>`:`<input id="f_${f.id}" ${f.num?'inputmode="numeric"':''} value="${esc(f.value==null?'':f.value)}" placeholder="${esc(f.ph||'')}" maxlength="${f.max||80}">`)).join('')+`<div style="height:16px"></div><button class="btn block" data-act="fsave">Save</button>${extra||''}`); formModal.cb=onSave; formModal.fields=fields; }
function coinFields(c){ return Object.keys(R.coins).reverse().map(k=>({id:k,label:R.coinNames[k]+' pieces',num:true,value:(c||{})[k]||0})); }
const num=v=>Math.max(0,parseInt(v,10)||0);

// ---------- sound: synthesized ambience and effects (no recordings) ----------
const SCENES=[['cave','Cave'],['dungeon','Halls'],['crypt','Crypt'],['river','River'],['forest','Forest'],['town','Keep'],['camp','Camp'],['battle','Battle'],['silence','Silence']];
const SND={on:LS.get('snd',false),vol:LS.get('vol',0.7),ctx:null,cur:null,curId:null};
function sndInit(){ if(SND.ctx) return true; const C=window.AudioContext||window.webkitAudioContext; if(!C) return false; const x=SND.ctx=new C(); SND.master=x.createGain(); SND.master.gain.value=SND.vol; SND.master.connect(x.destination);
  const len=x.sampleRate*2, mk=f=>{ const b=x.createBuffer(1,len,x.sampleRate); f(b.getChannelData(0)); return b; };
  SND.white=mk(d=>{ for(let i=0;i<len;i++) d[i]=Math.random()*2-1; }); SND.brown=mk(d=>{ let l=0; for(let i=0;i<len;i++){ l=(l+0.02*(Math.random()*2-1))/1.02; d[i]=l*3.5; } });
  const rl=Math.floor(x.sampleRate*3.2), ir=x.createBuffer(2,rl,x.sampleRate); for(let c=0;c<2;c++){ const d=ir.getChannelData(c); for(let i=0;i<rl;i++) d[i]=(Math.random()*2-1)*Math.pow(1-i/rl,2.6)*(i<x.sampleRate*0.012?i/(x.sampleRate*0.012):1); } SND.reverb=x.createConvolver(); SND.reverb.buffer=ir; return true; }
function sndScene(id){ const x=SND.ctx, out=x.createGain(); out.gain.value=0; out.connect(SND.master); out.gain.linearRampToValueAtTime(1,x.currentTime+2); const nodes=[], timers=[]; let alive=true;
  // dry and wet (reverb) buses: almost everything goes through the reverb so nothing sounds like a bare beep
  const dry=x.createGain(), wet=x.createGain(); dry.connect(out); wet.connect(SND.reverb); const wetOut=x.createGain(); wetOut.gain.value=0; SND.reverb.connect(wetOut); wetOut.connect(SND.master); wetOut.gain.linearRampToValueAtTime(1,x.currentTime+2);
  const rnd=(a,b)=>a+Math.random()*(b-a);
  const send=(node,d,w,pan)=>{ let n=node; if(x.createStereoPanner&&pan!==undefined){ const p=x.createStereoPanner(); p.pan.value=pan; n.connect(p); n=p; } const gd=x.createGain(); gd.gain.value=d; n.connect(gd); gd.connect(dry); const gw=x.createGain(); gw.gain.value=w; n.connect(gw); gw.connect(wet); };
  const bed=(buf,type,f,q,g,w)=>{ const s=x.createBufferSource(); s.buffer=buf; s.loop=true; const bq=x.createBiquadFilter(); bq.type=type; bq.frequency.value=f; bq.Q.value=q; const gn=x.createGain(); gn.gain.value=g; s.connect(bq); bq.connect(gn); send(gn,1,w||0); s.start(0,Math.random()*1.5); nodes.push(s); return gn.gain; };
  const every=(a,b,fn)=>{ const go=()=>{ if(!alive) return; if(!document.hidden) fn(); timers.push(setTimeout(go,rnd(a,b))); }; timers.push(setTimeout(go,rnd(a*0.3,b*0.6))); };
  // a water drop: a tiny upward chirp with a very short tail, placed left or right, mostly heard through the reverb
  const drip=(g,lo,hi)=>{ const t=x.currentTime, f=rnd(lo||900,hi||2100), o=x.createOscillator(), gn=x.createGain(), d=rnd(0.05,0.11); o.type='sine'; o.frequency.setValueAtTime(f*0.72,t); o.frequency.exponentialRampToValueAtTime(f,t+0.02); o.frequency.exponentialRampToValueAtTime(f*0.9,t+d); gn.gain.setValueAtTime(0.0001,t); gn.gain.exponentialRampToValueAtTime(g,t+0.004); gn.gain.exponentialRampToValueAtTime(0.0001,t+d); o.connect(gn); send(gn,0.25,1,rnd(-0.8,0.8)); o.start(t); o.stop(t+d+0.05); };
  const drops=(a,b,g)=>every(a,b,()=>{ drip(g); if(Math.random()<0.3) setTimeout(()=>alive&&drip(g*0.6),rnd(90,260)); });
  const noiseHit=(type,f,q,dur,g,w,pan)=>{ const t=x.currentTime, s=x.createBufferSource(); s.buffer=SND.white; const bq=x.createBiquadFilter(); bq.type=type; bq.frequency.value=f; bq.Q.value=q; const gn=x.createGain(); gn.gain.setValueAtTime(g,t); gn.gain.exponentialRampToValueAtTime(0.0001,t+dur); s.connect(bq); bq.connect(gn); send(gn,1,w||0,pan); s.start(t,Math.random()); s.stop(t+dur+0.05); };
  const thud=(f,dur,g,w)=>{ const t=x.currentTime, o=x.createOscillator(), gn=x.createGain(); o.frequency.setValueAtTime(f,t); o.frequency.exponentialRampToValueAtTime(f*0.45,t+dur); gn.gain.setValueAtTime(g,t); gn.gain.exponentialRampToValueAtTime(0.0001,t+dur); o.connect(gn); send(gn,0.8,w||0.5); o.start(t); o.stop(t+dur+0.05); };
  const fire=(g)=>{ bed(SND.brown,'lowpass',260,0.5,g*0.9,0.05); every(60,380,()=>noiseHit('highpass',rnd(1800,5000),0.7,rnd(0.012,0.05),rnd(0.02,0.09)*g*4,0.1,rnd(-0.5,0.5))); every(1500,5000,()=>noiseHit('bandpass',rnd(500,900),1,0.09,0.12*g*4,0.2)); };
  const bird=()=>{ const t=x.currentTime, f=rnd(2600,4200), n=2+Math.floor(Math.random()*4), pan=rnd(-0.9,0.9); for(let i=0;i<n;i++){ const o=x.createOscillator(), gn=x.createGain(), s=t+i*rnd(0.09,0.14); o.frequency.setValueAtTime(f*rnd(0.95,1.05),s); o.frequency.exponentialRampToValueAtTime(f*rnd(1.1,1.35),s+0.05); gn.gain.setValueAtTime(0.0001,s); gn.gain.exponentialRampToValueAtTime(0.03,s+0.01); gn.gain.exponentialRampToValueAtTime(0.0001,s+0.07); o.connect(gn); send(gn,0.5,0.6,pan); o.start(s); o.stop(s+0.1); } };
  ({ cave(){ bed(SND.brown,'lowpass',420,0.4,0.16,0.1); drops(1400,5200,0.11); every(9000,20000,()=>noiseHit('lowpass',300,0.5,2.2,0.05,0.8)); },
     dungeon(){ bed(SND.brown,'lowpass',300,0.4,0.2,0.1); drops(3500,9000,0.07); every(11000,24000,()=>thud(rnd(60,90),0.5,0.16,0.9)); every(300,1200,()=>noiseHit('highpass',rnd(2500,5000),0.7,0.02,0.012,0.2,0.6)); },
     crypt(){ bed(SND.brown,'lowpass',180,0.4,0.22,0.2); bed(SND.white,'bandpass',700,6,0.006,0.6); drops(7000,16000,0.05); every(14000,30000,()=>noiseHit('bandpass',rnd(350,600),4,3,0.03,1)); },
     forest(){ bed(SND.white,'bandpass',900,0.3,0.035,0.1); bed(SND.white,'highpass',4500,0.5,0.008,0); every(1200,5000,bird); every(7000,15000,()=>noiseHit('bandpass',rnd(1800,3000),0.6,1.4,0.03,0.2,rnd(-0.6,0.6))); },
     town(){ fire(0.2); every(6000,15000,()=>thud(rnd(110,160),0.12,0.07,0.4)); },
     river(){ bed(SND.white,'bandpass',700,0.35,0.07,0.15); bed(SND.white,'bandpass',2200,0.5,0.018,0.1); bed(SND.brown,'lowpass',350,0.4,0.2,0.1); drops(2500,7000,0.06); },
     camp(){ fire(0.24); every(700,1300,()=>{ const pan=rnd(-0.8,0.8); for(let i=0;i<3;i++) setTimeout(()=>{ if(!alive) return; const t=x.currentTime, o=x.createOscillator(), gn=x.createGain(); o.frequency.value=4300; gn.gain.setValueAtTime(0.0001,t); gn.gain.exponentialRampToValueAtTime(0.006,t+0.008); gn.gain.exponentialRampToValueAtTime(0.0001,t+0.04); o.connect(gn); send(gn,1,0.2,pan); o.start(t); o.stop(t+0.06); },i*60); }); },
     battle(){ bed(SND.brown,'lowpass',200,0.4,0.2,0.1); let k=0; const beat=()=>{ if(!alive) return; if(!document.hidden){ thud(85,0.32,0.5,0.5); if(k%2) setTimeout(()=>alive&&thud(78,0.26,0.3,0.5),330); if(k%4===3) setTimeout(()=>alive&&thud(120,0.18,0.24,0.5),495); } k++; timers.push(setTimeout(beat,660)); }; beat(); },
     silence(){} })[id]();
  return { stop(){ alive=false; timers.forEach(clearTimeout); const t=x.currentTime; [out,wetOut].forEach(gn=>{ gn.gain.cancelScheduledValues(t); gn.gain.setValueAtTime(gn.gain.value,t); gn.gain.linearRampToValueAtTime(0,t+1.5); }); setTimeout(()=>{ nodes.forEach(n=>{ try{ n.stop(); }catch(e){} }); try{ out.disconnect(); wet.disconnect(); wetOut.disconnect(); }catch(e){} },4500); } }; }
const TENSE=['Calm','Tense','Dread'];
function tenseLv(){ return sessionOpen()?Math.max(0,Math.min(2,+((st('scene')||{}).tense)||0)):0; }
function sndTense(lv){ const x=SND.ctx, out=x.createGain(); out.gain.value=0; out.connect(SND.master); out.gain.linearRampToValueAtTime(1,x.currentTime+3); const nodes=[], timers=[]; let alive=true; const rnd=(a,b)=>a+Math.random()*(b-a);
  const lp=x.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=lv===2?210:150; lp.Q.value=1.2; const dg=x.createGain(); dg.gain.value=lv===2?0.07:0.045; lp.connect(dg); dg.connect(out);
  (lv===2?[55,55.7,58.27]:[55,55.5]).forEach(f=>{ const o=x.createOscillator(); o.type='sawtooth'; o.frequency.value=f; o.connect(lp); o.start(); nodes.push(o); });
  const lfo=x.createOscillator(), lg=x.createGain(); lfo.frequency.value=0.07; lg.gain.value=60; lfo.connect(lg); lg.connect(lp.frequency); lfo.start(); nodes.push(lfo);
  const thud=(g,when)=>{ const t=x.currentTime+when, o=x.createOscillator(), gn=x.createGain(); o.frequency.setValueAtTime(62,t); o.frequency.exponentialRampToValueAtTime(34,t+0.2); gn.gain.setValueAtTime(0.0001,t); gn.gain.exponentialRampToValueAtTime(g,t+0.012); gn.gain.exponentialRampToValueAtTime(0.0001,t+0.24); o.connect(gn); gn.connect(out); o.start(t); o.stop(t+0.3); };
  const beat=()=>{ if(!alive) return; if(!document.hidden){ thud(lv===2?0.55:0.38,0); thud(lv===2?0.4:0.26,0.19); } timers.push(setTimeout(beat,lv===2?760:1150)); }; beat();
  const swell=()=>{ if(!alive) return; if(!document.hidden){ const t=x.currentTime, base=lv===2?rnd(1100,1500):rnd(500,700); [1,1.059].forEach(m=>{ const o=x.createOscillator(), gn=x.createGain(); o.type='sine'; o.frequency.setValueAtTime(base*m,t); o.frequency.linearRampToValueAtTime(base*m*(lv===2?1.04:0.98),t+5); gn.gain.setValueAtTime(0.0001,t); gn.gain.exponentialRampToValueAtTime(lv===2?0.014:0.008,t+2.2); gn.gain.exponentialRampToValueAtTime(0.0001,t+5); o.connect(gn); gn.connect(out); o.start(t); o.stop(t+5.2); }); } timers.push(setTimeout(swell,lv===2?rnd(7000,13000):rnd(14000,26000))); }; timers.push(setTimeout(swell,rnd(2000,5000)));
  return { stop(){ alive=false; timers.forEach(clearTimeout); const t=x.currentTime; out.gain.cancelScheduledValues(t); out.gain.setValueAtTime(out.gain.value,t); out.gain.linearRampToValueAtTime(0,t+2); setTimeout(()=>{ nodes.forEach(n=>{ try{ n.stop(); }catch(e){} }); try{ out.disconnect(); }catch(e){} },2600); } }; }
