const THEMES={gold:['Forged gold','#fff0b8','#c8922e','#241703'],ruby:['Ruby','#ff8a8a','#96182a','#fff'],sapphire:['Sapphire','#8fc0ff','#2a4fa8','#fff'],emerald:['Emerald','#8ff0c0','#14704a','#fff'],amethyst:['Amethyst','#d9c2ff','#5d3a9a','#fff'],bone:['Old bone','#fffaf0','#b9ab8c','#2a2218'],obsidian:['Obsidian','#6a6478','#15121c','#ffe29a'],dragonfire:['Dragonfire','#ffd36a','#e2401c','#fff']};
