    const t=THEMES[theme]; const burst=(nat===20||(v&&v[1]))?26:(v&&!v[1])?0:12; let ps=''; for(let i=0;i<burst;i++){ const a=Math.random()*6.283, r=70+Math.random()*130; ps+=`<i class="dx-p" style="--x:${Math.cos(a)*r}px;--y:${Math.sin(a)*r}px;background:${i%3===0?'#7ef0c0':i%3===1?t[1]:'#ffd27a'};animation-delay:${Math.random()*80}ms"></i>`; } dx.querySelector('.dx-row').insertAdjacentHTML('beforeend',ps);
    if(nat===20) sfx('chime'); else if(nat===1||(v&&!v[1])) sfx('drum'); try{ navigator.vibrate&&navigator.vibrate(nat===20?[60,40,120]:40); }catch(e){}
