function pi(n,size,w){ return `<svg class="pic" aria-hidden="true" width="${size||20}" height="${size||20}" viewBox="0 0 24 24" stroke-width="${w||1.8}"><path d="${PIC[n]||PIC.star}"/></svg>`; }
const CLSIC={fighter:'sword',cleric:'cross',magicuser:'spark',thief:'key',dwarf:'hammer',elf:'leaf',halfling:'foot',paladin:'shield',ranger:'bow',druid:'leaf',illusionist:'spark',assassin:'key',monk:'star'};
const CONDIC={paralyzed:'target',asleep:'moon',charmed:'star',poisoned:'drop',blinded:'x',held:'target',stone:'shield',webbed:'web',afraid:'skull',cursed:'skull',diseased:'drop',burning:'flame',invisible:'spark',hidden:'moon',tired:'moon',drained:'skull',down:'minus'};
function hpTone(d){ const p=d.hpMax?d.hp/d.hpMax:0; return d.dead?'#5b6272':p<=.34?'#ff7272':p<=.6?'#ffb454':'#7ef0c0'; }
function ringGap(p,c){ const g=Math.round(310*Math.max(0,Math.min(100,p))/100); return `conic-gradient(from 160deg, ${c} 0deg ${g}deg, #2a3040 ${g}deg 310deg, transparent 310deg 360deg)`; }
const ACSVG='<svg aria-hidden="true" width="50" height="58" viewBox="0 0 56 64"><defs><linearGradient id="acRim" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#cfe0ff"/><stop offset=".45" stop-color="#7fa6ee"/><stop offset="1" stop-color="#4a74cf"/></linearGradient><linearGradient id="acL" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3f70d6"/><stop offset="1" stop-color="#2449a6"/></linearGradient><linearGradient id="acR" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3160c4"/><stop offset="1" stop-color="#1b3a8c"/></linearGradient></defs><path d="M4 8.500Q17 9.500 28 3.500 39 9.500 52 8.500V30C52 44.500 42 54.500 28 61.500 14 54.500 4 44.500 4 30Z" fill="url(#acRim)"/><path d="M28 8.200Q38.500 13 48.500 12.600V30C48.500 42.300 40 51 28 57.300Z" fill="url(#acR)"/><path d="M28 8.200Q17.500 13 7.500 12.600V30C7.500 42.300 16 51 28 57.300Z" fill="url(#acL)"/><path d="M28 8.200Q38.500 13 48.500 12.600V30C48.500 42.300 40 51 28 57.300 16 51 7.500 42.300 7.500 30V12.600Q17.500 13 28 8.200Z" fill="none" stroke="#10245a" stroke-opacity=".7" stroke-width="1.200"/></svg>';
function foeState(x){ const p=x.hpMax?x.hp/x.hpMax:1; return x.hp<=0?'<span class="fst n">Down</span>':p<=.34?'<span class="fst n">Nearly dead</span>':p<1?'<span class="fst w">Wounded</span>':'<span class="fst">Unhurt</span>'; }
// ---------- conditions ----------
const CONDS=[['paralyzed','Paralyzed','Cannot move or act. Attackers hit automatically.'],['asleep','Asleep','Helpless until woken.'],['charmed','Charmed','Treats the charmer as a trusted friend.'],['poisoned','Poisoned','As the DM rules: often save or die.'],['blinded','Blinded','Cannot see; -4 to hit and easy to hit.'],['held','Held','Held in place by magic.'],['stone','Turned to stone','Petrified until restored.'],['webbed','Webbed','Stuck in webs; 2-8 turns to break free.'],['afraid','Afraid','Must flee or cannot advance.'],['cursed','Cursed','Under a curse the DM describes.'],['diseased','Diseased','Sick and weakened.'],['burning','Burning','Covered in flaming oil: 1d8 for 2 rounds.'],['invisible','Invisible','Unseen until attacking or casting.'],['hidden','Hidden','Unseen in shadow or cover.'],['tired','Tired','No rest in 6 turns: -1 to hit and damage.'],['drained','Level drained','Lost a level to the undead.'],['down','Down','Out of the fight (table rule).']];
