function hashStr(s){ let h=2166136261; for(const c of String(s)) h=Math.imul(h^c.charCodeAt(0),16777619)>>>0; return h; }
function letters(seed,name){ const h=hashStr(seed), G=[['#ef4b5b','#7a1220'],['#5b8ff0','#1c3a80'],['#5fe0a0','#14704a'],['#f0c868','#8f6418'],['#b79cff','#4a2a8a'],['#ff9a5a','#8a3a12'],['#5fd6e0','#14606a']], g=G[h%G.length], g2=G[(h>>>4)%G.length], ang=(h>>>8)%360, pat=(h>>>12)%3;
  const bg=pat===0?`linear-gradient(${ang}deg,${g[0]},${g[1]})`:pat===1?`conic-gradient(from ${ang}deg,${g[1]},${g[0]},${g2[1]},${g[1]})`:`radial-gradient(circle at ${20+(h>>>16)%60}% ${20+(h>>>20)%60}%,${g[0]},${g[1]} 70%)`; return `<span class="lt" style="background:${bg}">${esc(initials(name))}</span>`; }
// ---------- chat and activity ----------
S.chatCh='table'; S.trk='now';
function viewChat(v){ viewFeed(v,'chat'); }
// ---------- play: the in-session gamepad ----------
function playChar(){ const mine=myChars().filter(c=>!c.data.dead); return mine.find(c=>c.id===S.playId)||mine[0]||myChars()[0]||null; }
function viewPlay(v){ const pc=playChar(), open=sessionOpen();
  if(!pc){ v.innerHTML=(isDM()?`<div class="card"><h2>Dungeon Master</h2><div class="small mute" style="margin-bottom:10px">Your quick rolls. The clock, combat and place are on the Tracker; monsters and treasure are under Lore.</div><div class="pad">${R.quickRolls.map(q=>`<button class="padb" data-act="qroll" data-ch="dm" data-n="${q.n}" data-s="${q.s}" data-label="${esc(q.label)}">${pi('dice',22)}<b>${esc(q.label.replace(/ \(.*/,''))} <small>(${q.n}d${q.s})</small></b></button>`).join('')}<button class="padb" data-act="dice">${pi('dice',22)}<b>Any dice <small>(pick)</small></b></button></div></div>`:`<div class="card"><h2>No character yet</h2><div class="empty">Roll up a character and this becomes your gamepad.</div><button class="btn block" data-act="newchar">Create a character</button></div>`); return; }
  const d=pc.data, k0=d.classes[0]||{}, pct=d.hpMax?Math.max(0,Math.min(100,100*d.hp/d.hpMax)):0, t=now(), T=R.T, tone=hpTone(d); const mine=myChars().filter(c=>!c.data.dead);
  const light=(st('lights')||[]).filter(l=>l.who===d.name&&l.lit!==false&&(l.end==null||l.end>t))[0]; const mem=(d.mem||[]).filter(m=>!m.cast);
  const conds=(d.cond||[]).map(id=>CONDS.find(c=>c[0]===id)).filter(Boolean); const sel=conds.find(c=>c[0]===S.condSel)||conds[0]; const thief=k0.id&&R.thiefFor(k0.id,k0.level,d.race,d.ab.dex); const turn=R.turn&&k0.id==='cleric';
  const others=CH().filter(c=>c.id!==pc.id&&!c.data.dead);
  const acts=[['attack','Attack','d20','sword'],['missile','Shoot or throw','d20','bow'],['save','Saving throw','d20','shield'],...(mem.length?[['spell','Cast a spell',mem.length+' ready','spark']]:[]),...(thief?[['skill','Thief skill','d%','key']]:[]),...(turn?[['turn','Turn undead','2d6','cross']]:[]),['door','Force a door','d6','door'],['search','Search','d6','search'],['listen','Listen','d6','ear'],['init','Initiative','d6','hour'],['any','Any dice','pick','dice']];
  const cbt=st('combat')||{};
  v.innerHTML=`${cbt.on?`<button class="fightbar" data-act="gotrack">${pi('sword',18)}<span class="grow"><b>Combat · round ${cbt.round||1}</b><small>${cbt.init?(cbt.init[0]>cbt.init[1]?'The party acts first':cbt.init[0]<cbt.init[1]?'The monsters act first':'Both sides act together'):'Initiative not rolled yet'}</small></span>${pi('chev',18)}</button>`:''}${others.length?`<button class="mini" data-act="tab" data-tab="sheet"><span class="grow">Party</span>${others.slice(0,5).map(c=>{ const o=c.data, p=o.hpMax?Math.max(0,Math.min(100,100*o.hp/o.hpMax)):0, tc=hpTone(o); return `<span class="mr ${tc==='#ff7272'?'low':''}" role="img" aria-label="${esc(o.name)}, ${o.hp} of ${o.hpMax} hit points" style="background:conic-gradient(${tc} ${p}%, #2a3040 0)"><span class="av">${avatar(c)}</span></span>`; }).join('')}${pi('chev',18)}</button>`:''}
  ${mine.length>1?`<div class="pills" style="padding:0 0 10px">${mine.map(c=>`<button class="pill ${c.id===pc.id?'on':''}" data-act="playpick" data-id="${c.id}">${esc(c.data.name)}</button>`).join('')}</div>`:''}
  <div class="card pcard"><div class="pc-top"><span class="bigw"><button class="bigr ${tone==='#ff7272'?'low':''}" data-act="herocard" data-id="${pc.id}" aria-label="Open ${esc(d.name)}'s hero card" style="background:${ringGap(pct,tone)}"><span class="av">${avatar(pc)}</span></button><span class="cbadge" aria-hidden="true">${pi(CLSIC[k0.id]||'star',16,2)}</span></span><div class="grow"><div class="pc-n">${esc(d.name)}</div><div class="pc-m">${esc(classLine(d))}${d.align?' · '+esc(d.align):''}</div></div><div class="acs" role="img" aria-label="Armor class ${calcAC(d)}">${ACSVG}<span>AC</span><b>${calcAC(d)}</b></div></div>
   <div class="hprow"><button class="sq" data-act="hpq" data-d="-1" aria-label="Lose 1 hit point" ${open?'':'disabled'}>${pi('minus',24)}</button><div class="hpmid"><div class="hpbig" style="color:${tone};text-shadow:0 0 22px ${tone}77">${d.hp}<span>/</span>${d.hpMax}</div><small>Hit points</small></div><button class="sq" data-act="hpq" data-d="1" aria-label="Gain 1 hit point" ${open?'':'disabled'}>${pi('plus',24)}</button></div>
   <div class="stz">${conds.length?conds.map(c=>`<button class="stc ${sel&&sel[0]===c[0]?'on':''}" data-act="condsel" data-id="${c[0]}" aria-pressed="${sel&&sel[0]===c[0]}">${pi(CONDIC[c[0]]||'star',16)}${esc(c[1])}<span class="stx" data-act="condoff" data-id="${c[0]}" role="button" aria-label="Remove ${esc(c[1])}">${pi('x',14)}</span></button>`).join(''):'<span class="stc none">No status</span>'}<button class="stplus" data-act="condadd" aria-label="Add a status"><i>${pi('plus',18)}</i></button><span class="sthelp">${sel?esc(sel[1]+': '+sel[2]):'Nothing is affecting '+esc(d.name)+' right now.'}</span></div></div>
  <div class="tiles">${light?`<button class="tile torch" data-act="tab" data-tab="tracker" aria-label="${esc(light.name)} lit">${pi('flame',28)}<span>${esc(light.name)} · ${light.end==null?'lit':Math.max(1,Math.ceil((light.end-t)/T.turn))+' turns'}</span></button>`:`<button class="tile dark" data-act="playlight" aria-label="No light. Light one"><b>—</b><span>No light</span></button>`}<button class="tile gold" data-act="coins" aria-label="Gold"><b>${Math.floor(wealthCp(d)/R.coins.gp).toLocaleString()}</b><span>Gold</span></button><button class="tile spell" data-act="${mem.length?'pa':'tab'}" data-k="spell" data-tab="sheet" data-keep="1" aria-label="Spells ready"><span class="corner">${pi('spark',20)}</span><b>${mem.length}</b><span>Spell${mem.length===1?'':'s'}</span></button></div>
  <div class="card">${open?'':'<div class="warn" style="margin:0 0 10px">The game is paused. Rolls and hit points open when a session begins.</div>'}<div class="pad">${acts.map(a=>`<button class="padb" data-act="pa" data-k="${a[0]}" ${open?'':'disabled'}>${pi(a[3],22)}<b>${a[1]} <small>(${a[2]})</small></b></button>`).join('')}</div></div>
  <div class="card"><h2>Just now<span class="sp"></span><button class="btn ghost sm" data-act="seeactivity">All activity</button></h2><div id="play_log"></div></div>`;
  drawPlayLog(); }
function drawPlayLog(){ const el=$('#play_log'); if(!el) return; const ms=S.msgs.filter(m=>m.ch!=='players'&&m.k!=='chat').slice(-4).reverse(); el.innerHTML=ms.length?ms.map(m=>{ if(m.k==='roll'){ const b=m.b, vd=verdict(b); return `<div class="li" style="padding:7px 0"><div class="t">${esc(b.label||'Dice roll')}<small>${esc(memberName(m.u))}${vd?' · '+esc(vd[0]):''}</small></div><b class="gold" style="font:900 20px var(--head)">${b.sets.map(s=>s.total).join(' · ')}</b></div>`; } return `<div class="li" style="padding:7px 0"><div class="t small">${esc(eventText(m))}</div></div>`; }).join(''):'<div class="small mute">Nothing yet this session.</div>'; }
function playPre(){ const pc=playChar(); if(pc) S.charId=pc.id; return pc; }
function playAction(k){ const pc=playPre(); if(!pc) return; const d=pc.data, k0=d.classes[0], nm=d.name, sv=R.strength(d.ab.str,d.strPct), dx=R.dex[Math.max(3,Math.min(19,d.ab.dex))]; const thac=R.toHitRow?19:null; const demi=k0&&['dwarf','elf','halfling'].includes(k0.id)||['dwarf','elf','halfling','gnome','halfelf'].includes(d.race);
  const list=(title,rows,empty)=>modal(title,rows.length?rows.join(''):`<div class="empty">${empty}</div>`); const row=(label,sub,attrs)=>`<button class="btn sec block" style="margin-bottom:8px;justify-content:space-between;text-align:left" ${attrs}><span>${esc(label)}</span><span class="mute small">${esc(sub||'')}</span></button>`;
  if(k==='attack'||k==='missile'){ const ws=(d.weapons||[]).map(w=>({w,inf:weaponInfo(w.n)})).filter(x=>k==='attack'?true:!!x.inf.mi); const rows=ws.map((x,i)=>row(x.w.n,(x.inf.d?x.inf.d.sm:'')+(k==='missile'&&x.inf.mi?' · '+x.inf.mi.r.join('/')+R.rangeUnit:''),`data-act="pa2" data-k="${k}" data-w="${esc(x.w.n)}"`)); if(k==='attack') rows.push(row('Fists or something else','1-2',`data-act="pa2" data-k="attack" data-w=""`)); return list(k==='attack'?'Attack with…':'Shoot or throw…',rows,'No missile weapons on your sheet. Add one under Party.'); }
  if(k==='save'){ const svs=R.savesFor?R.savesFor(d).slice(0,5):['Paralyzation, poison or death','Petrification or polymorph','Rod, staff or wand','Breath weapon','Spell'].map((n,i)=>[n,(d.saves&&d.saves[i])||'']); const wm=R.mod?R.mod(Math.max(3,Math.min(18,d.ab.wis))):0; return list('Save against…',svs.map((s,i)=>row(s[0],s[1]?'needs '+s[1]:'',`data-act="pa2" data-k="save" data-i="${i}" data-t="${esc(s[1])}" data-n="${esc(s[0])}" data-m="${R.mod&&[1,2,4].includes(i)?wm:0}"`)),''); }
  if(k==='spell'){ const mem=(d.mem||[]).map((m,i)=>Object.assign({i},m)).filter(m=>!m.cast); return list('Cast…',mem.map(m=>{ const inf=((R.spellInfo||{})[m.list]||{})[m.n]; return `<button class="btn sec block" style="margin-bottom:8px;flex-direction:column;align-items:flex-start;text-align:left" data-act="cast" data-i="${m.i}"><span>${esc(m.n)}</span>${inf?`<span class="small mute" style="font-weight:400">Range ${esc(inf[0])} · ${esc(inf[1])}<br>${esc(inf[2])}</span>`:''}</button>`; }),'No spells memorized.'); }
  if(k==='skill'){ const t=R.thiefFor(k0.id,k0.level,d.race,d.ab.dex); return list('Thief skill',t.map((val,i)=>val==null?'':row(R.thiefNames[i],typeof val==='string'?val:val+'%',`data-act="pa2" data-k="skill" data-n="${esc(R.thiefNames[i])}" data-t="${esc(val)}"`)),''); }
  if(k==='turn'){ const col=Math.min(k0.level,3); return list('Turn which undead?',R.turn.map(r=>row(r[0],r[col]==='T'?'automatic':r[col]==='—'?'no effect':'needs '+r[col],`data-act="pa2" data-k="turn" data-n="${esc(r[0])}" data-t="${esc(r[col])}"`)),''); }
  if(k==='door') return askRoll({title:'Force a door',label:`${nm} forces a door`,n:1,s:6,help:R.id==='basic'?'A 1 or 2 opens it. Your strength shifts the number needed.':'Your open doors chance is '+sv[3]+' in 6.',meta:{cmp:'le',target:R.id==='basic'?Math.max(0,Math.min(5,2+sv[0])):parseInt(String(sv[3]).split('-').pop(),10)||1}});
  if(k==='listen') return askRoll({title:'Listen',label:`${nm} listens`,n:1,s:6,help:'Once per door. Dwarves, elves and halflings hear on a 1 or 2.',meta:{cmp:'le',target:demi?2:1}});
  if(k==='search') return list('Search for…',[row('Secret doors',(k0&&k0.id==='elf'||d.race==='elf')?'1 or 2 on d6':'1 on d6',`data-act="pa2" data-k="search" data-n="secret doors" data-t="${(k0&&k0.id==='elf'||d.race==='elf')?2:1}"`),row('Traps',(k0&&k0.id==='dwarf'||d.race==='dwarf')?'1 or 2 on d6':'1 on d6',`data-act="pa2" data-k="search" data-n="traps" data-t="${(k0&&k0.id==='dwarf'||d.race==='dwarf')?2:1}"`)],'');
  if(k==='init'){ const cb=st('combat')||{}; if(cb.on&&cb.init) return toast(`Already rolled this round: ${cb.init[0]>cb.init[1]?'the party acts first':cb.init[0]<cb.init[1]?'the monsters act first':'both sides act together'}`); if(!canRun()) return toast(cb.on?'The Dungeon Master rolls initiative. You’ll see who goes first here.':'The Dungeon Master starts the fight. You’ll see it here.'); return actions.init(); }
  if(k==='any') return diceModal(); }
function playAction2(el){ const pc=playPre(); if(!pc) return; const d=pc.data, k0=d.classes[0], nm=d.name, k=el.dataset.k, sv=R.strength(d.ab.str,d.strPct), dx=R.dex[Math.max(3,Math.min(19,d.ab.dex))], thac=R.toHitRow?19:null;
  if(k==='attack'||k==='missile'){ const w=el.dataset.w, inf=w?weaponInfo(w):{}, mod=(k==='attack'?sv[0]:dx[0]+(k0&&k0.id==='halfling'?1:0)), dm=inf.d?parseDice(inf.d.sm):[1,2,0], dmod=dm[2]+(k==='attack'?sv[1]:0);
    return askRoll({title:k==='attack'?'Attack':'Shoot or throw',label:`${nm} attacks${w?' with '+w:''}`,mod,help:(thac?'The result tells you the armor class you hit. ':'')+(mod?`Your ${k==='attack'?'strength':'dexterity'} adjustment is already added.`:'')+(k==='missile'?' Add +1 at short range, -1 at long.':''),meta:{kind:'attack',thac},
      then:()=>`<button class="btn" data-act="padmg" data-n="${dm[0]}" data-s="${dm[1]}" data-m="${dmod}" data-l="${esc(nm+' damage'+(w?' with '+w:''))}">Roll damage (${dm[0]}d${dm[1]}${dmod?(dmod>0?'+':'')+dmod:''})</button>`}); }
  if(k==='save'){ const t=parseInt(el.dataset.t,10); return askRoll({title:'Saving throw',label:`${nm} saves vs. ${el.dataset.n.toLowerCase()}`,mod:+el.dataset.m||0,help:(+el.dataset.m?'Your wisdom adjustment is added for magic. ':'')+(isNaN(t)?'Ask your DM for the number you need.':''),meta:isNaN(t)?{}:{cmp:'ge',target:t}}); }
  if(k==='skill'){ const tv=el.dataset.t; if(/d6/.test(tv)) return askRoll({title:'Thief skill',label:`${nm}: ${el.dataset.n}`,n:1,s:6,meta:{cmp:'le',target:parseInt(tv.split('-')[1],10)||2}}); return askRoll({title:'Thief skill',label:`${nm}: ${el.dataset.n}`,n:1,s:100,meta:{cmp:'le',target:Math.floor(parseFloat(tv))}}); }
  if(k==='turn'){ const t=el.dataset.t; if(t==='—') return toast('That is beyond your power for now',true); const then=()=>`<button class="btn" data-act="padmg" data-n="2" data-s="6" data-m="0" data-l="${esc(nm+': hit dice of undead turned')}">Roll hit dice turned (2d6)</button>`; if(t==='T'){ closeModal(); RS={label:`${nm}: hit dice of ${el.dataset.n.toLowerCase()}s turned`,n:2,s:6,mod:0,ch:'table'}; return askRoll(Object.assign({title:'Turned automatically',help:'They turn without a roll. Roll for how many hit dice are affected.'},RS)); } return askRoll({title:'Turn undead',label:`${nm} turns ${el.dataset.n.toLowerCase()}s`,n:2,s:6,meta:{cmp:'ge',target:+t},then}); }
  if(k==='search') return askRoll({title:'Search',label:`${nm} searches for ${el.dataset.n}`,n:1,s:6,help:'Searching a 10 by 10 foot area takes a turn.',meta:{cmp:'le',target:+el.dataset.t}}); }
// ---------- sessions and recaps ----------
S.seenRecap=LS.get('seenRecap',{});
function unseenRecap(){ const r=((st('session')||{}).recaps||[])[0]; return !!(r&&(S.seenRecap[S.cid]||0)<r.at); }
function eventText(m){ const who=memberName(m.u); return m.b.text.startsWith(': ')?m.b.text.slice(2).replace(/^./,c=>c.toUpperCase()):who+' '+m.b.text; }
function recapLines(fromId,startT){ const ev=S.msgs.filter(m=>m.id>fromId&&m.ch==='table'); let wounds=0,heals=0,casts=0,rolls=0; const out=[];
  ev.forEach(m=>{ if(m.k==='roll'){ rolls++; return; } if(m.k!=='event') return; const t=eventText(m); if(/takes \d+ damage/.test(t)){ wounds++; return; } if(/heals \d+ hit points/.test(t)){ heals++; return; } if(/ casts /.test(t)){ casts++; return; } if(/lights a |burned out| ended$|updated the party treasure|began session|wrapped up session|Catch up/.test(t)) return; if(out[out.length-1]!==t) out.push(t.slice(0,180)); });
  const lines=out.slice(-40); const stats=[rolls?rolls+' dice roll'+(rolls>1?'s':''):'',wounds?wounds+' wound'+(wounds>1?'s':'')+' taken':'',heals?heals+' healing'+(heals>1?'s':''):'',casts?casts+' spell'+(casts>1?'s':'')+' cast':''].filter(Boolean).join(' · ');
  if(startT!=null){ const d=now()-startT, T=R.T; if(d>0) lines.unshift('Game time passed: '+(d>=T.day?Math.floor(d/T.day)+' day'+(Math.floor(d/T.day)>1?'s ':' '):'')+(Math.floor((d%T.day)/T.hour)?Math.floor((d%T.day)/T.hour)+' hour'+(Math.floor((d%T.day)/T.hour)>1?'s ':' '):'')+(Math.floor((d%T.hour)/T.turn)?Math.floor((d%T.hour)/T.turn)+' turn'+(Math.floor((d%T.hour)/T.turn)>1?'s':''):'')); }
  if(stats) lines.push(stats); return lines; }
function recapHTML(r){ return `${r.note?`<div class="card" style="margin:8px 0;white-space:pre-wrap">${esc(r.note)}</div>`:''}${(r.lines||[]).length?`<ul style="margin:6px 0">${r.lines.map(l=>`<li>${esc(l)}</li>`).join('')}</ul>`:'<div class="small mute">Nothing was logged.</div>'}`; }
